node -I -e '
const fs=require("fs");const j=JSON.parse(fs.readFileSync(process.argv[1]));
const d=j.data; const names=Object.keys(d); console.log("species:",names.length);
console.log("keys of one species:",Object.keys(d["Rillaboom"]));
for (const n of ["Rillaboom","Salamence-Mega","Indeedee-F","Urshifu-Rapid-Strike","Mimikyu"]) { const s=d[n]; if(!s){console.log(n,"missing");continue;}
  const sp=Object.entries(s.Spreads).sort((a,b)=>b[1]-a[1]); const tot=sp.reduce((a,[,w])=>a+w,0); const ab=Object.values(s.Abilities).reduce((a,b)=>a+b,0);
  console.log(n,"spreads:",sp.length,"sum:",tot,"abil:",ab,"raw:",s["Raw count"],"usage:",s.usage,"\n  top:",sp.slice(0,5).map(([k,w])=>k+"="+w).join(" | "),"\n  tail:",sp.slice(-2).map(([k,w])=>k+"="+w).join(" | "));
}
const nat=new Set(); let bad=0; for(const n of names) for(const k of Object.keys(d[n].Spreads)){ nat.add(k.split(":")[0]); if(!/^[A-Z][a-z]+:\d+\/\d+\/\d+\/\d+\/\d+\/\d+$/.test(k)) bad++; }
console.log("natures:",[...nat].join(","),"| nonmatching keys:",bad);
console.log("hyphen names:",names.filter(n=>/[^A-Za-z]/.test(n)).slice(0,15).join(", "));
