S=/private/tmp/claude-501/-Users-kevin-pokemon-projects-vgc-usage-stats/73bb950b-54df-446f-b795-11177b357287/scratchpad && mkdir -p $S/scripts && cat > $S/scripts/make-fixture.js <<'EOF'
// Build trimmed chaos fixtures from a real chaos file.
// usage: node make-fixture.js <raw.json> <out-dir>
const fs = require("fs");
const path = require("path");
const [raw, outDir] = process.argv.slice(2);
const j = JSON.parse(fs.readFileSync(raw, "utf8"));

// species -> number of top spreads to keep (plus one zero-weight spread for Rillaboom)
const pick = { "Rillaboom": 4, "Salamence-Mega": 4, "Indeedee-F": 3, "Kommo-o": 3 };

function trim(name, n, extraSpreads = {}) {
  const s = j.data[name];
  const sorted = Object.entries(s.Spreads).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
  const kept = Object.fromEntries(sorted.slice(0, n));
  if (name === "Rillaboom") {
    const zero = sorted.find(([, w]) => w === 0);
    kept[zero[0]] = 0;
  }
  Object.assign(kept, extraSpreads);
  const total = Object.values(kept).reduce((a, b) => a + b, 0);
  // Abilities: keep the real names, scale so they sum to the kept spread weight.
  const abil = Object.entries(s.Abilities).sort((a, b) => b[1] - a[1]).slice(0, 2);
  const abilTotal = abil.reduce((a, [, w]) => a + w, 0);
  const abilities = {};
  let acc = 0;
  abil.forEach(([k, w], i) => {
    const v = i === abil.length - 1 ? total - acc : w / abilTotal * total;
    abilities[k] = v;
    acc += v;
  });
  const item = Object.entries(s.Items).sort((a, b) => b[1] - a[1])[0][0];
  return {
    "Raw count": s["Raw count"],
    "Viability Ceiling": s["Viability Ceiling"],
    "Abilities": abilities,
    "Items": { [item]: total },
    "Spreads": kept,
    "Moves": {},
    "Tera Types": { "nothing": total },
    "Happiness": { "255": total },
    "Teammates": {},
    "Checks and Counters": {},
    "usage": s.usage,
  };
}

const info = { ...j.info, "number of battles": 1000 };
const small = { info, data: {} };
for (const [name, n] of Object.entries(pick)) small.data[name] = trim(name, n);

const invalid = { info, data: {} };
for (const [name, n] of Object.entries(pick)) {
  invalid.data[name] = trim(name, n, name === "Rillaboom" ? { "Adamant:32/32/0/0/2/40": 1.5 } : {});
}

fs.writeFileSync(path.join(outDir, "chaos-small.json"), JSON.stringify(small, null, 1) + "\n");
fs.writeFileSync(path.join(outDir, "chaos-invalid.json"), JSON.stringify(invalid, null, 1) + "\n");

// Expected table for the valid fixture: every kept spread as the parser should see it.
const rows = [];
for (const [name, s] of Object.entries(small.data)) {
  const total = Object.values(s.Spreads).reduce((a, b) => a + b, 0);
  const entries = Object.entries(s.Spreads).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
  for (const [key, weight] of entries) {
    const [nature, nums] = key.split(":");
    const [hp, atk, def, spa, spd, spe] = nums.split("/").map(Number);
    rows.push({ species: name, spread: key, nature, sp: { hp, atk, def, spa, spd, spe }, weight, share: weight / total });
  }
}
fs.writeFileSync(path.join(outDir, "expected-spreads.json"), JSON.stringify(rows, null, 1) + "\n");
console.log("wrote", Object.keys(small.data).length, "species,", rows.length, "rows");
EOF
